// Single source of truth for the photos used across the site.
//
// Photos are auto-discovered from /public/images via imageManifest.js
// (regenerated by `npm run manifest`). For each file we attach:
//
//   - src       : URL ready for <img>
//   - caption   : curated text if listed below, otherwise a stable random
//                 line from captionPool (same line on every page load
//                 because we hash the filename — feels intentional, not random)
//   - chapter   : group tag (vows / tender / everyday / adventures /
//                 celebrations / little-one)
//   - focusY    : where to anchor the face when object-fit crops
//                 (0 = top of the photo, 100 = bottom; default 28% works
//                 for most upper-body selfies)
//   - isScan    : true ONLY for the ultrasound; gets its own reverent finale
//
// To add a new image: drop the file in /public/images, restart `npm run dev`.
// To add a curated caption: extend `curated` below.

import { imageManifest, optimizedSet, responsiveWidths } from './imageManifest.js'
import { hashCode } from '../utils/shuffle.js'

const base = '/images'
const optBase = '/images-opt'

function buildSrcSet(file) {
  if (!optimizedSet.has(file)) return undefined
  const dot = file.lastIndexOf('.')
  const name = file.slice(0, dot)
  return responsiveWidths
    .map((w) => `${optBase}/${name}-${w}.webp ${w}w`)
    .join(', ')
}

// Files that must be treated as "the scan" (ultrasound) — never appear in
// the random slideshow; reserved for the dedicated ScanReveal section.
const SCAN_FILES = new Set([
  'IMG_1887.jpg',
])

