  'IMG_5416.jpg': { caption: 'Two lives, one beginning',                      chapter: 'vows',         focusY: 25 },

  // ── Tender close-ups ──────────────────────────────────────────────────────
  'IMG_0673.jpg': { caption: 'A quiet, ordinary kind of perfect',             chapter: 'tender',       focusY: 35 },
  'IMG_1206.jpg': { caption: 'The way you look at me',                        chapter: 'tender',       focusY: 30 },
  'IMG_1567.jpg': { caption: 'Lights low, hearts loud',                       chapter: 'tender',       focusY: 30 },
  'IMG_1843.jpg': { caption: 'Salt air, soft hands, you',                     chapter: 'tender',       focusY: 28 },
  'IMG_2027.jpg': { caption: 'Blessed — by the gods and by you',              chapter: 'tender',       focusY: 22 },
  'IMG_1655.jpg': { caption: 'Closer than words',                             chapter: 'tender',       focusY: 28 },
  'IMG_1656.jpg': { caption: 'Of all my hellos, you are my forever',          chapter: 'tender',       focusY: 28 },
