// ── Build the unified photo array ────────────────────────────────────────────
export const photos = imageManifest.map((file) => {
  const c = curated[file] || {}
  const captionFromPool = captionPool[hashCode(file) % captionPool.length]
  return {
    file,
    src: `${base}/${file}`,
    srcSet: buildSrcSet(file),
    caption: c.caption || captionFromPool,
    chapter: c.chapter || 'everyday',
    focusY: typeof c.focusY === 'number' ? c.focusY : 28,
    isScan: SCAN_FILES.has(file),
  }
})

export const nonScanPhotos = photos.filter((p) => !p.isScan)
export const scanPhoto = photos.find((p) => p.isScan)

// Helper: format a photo's focusY into a CSS object-position string.
export function objectPosition(photo) {
  const y = photo?.focusY ?? 28
  return `center ${y}%`
}

export const chapters = [
  { id: 'vows',         label: 'The Vow' },
  { id: 'tender',       label: 'Tender' },
  { id: 'everyday',     label: 'Everyday' },
  { id: 'adventures',   label: 'Adventures' },
  { id: 'celebrations', label: 'Celebrations' },
  { id: 'little-one',   label: 'Little One' },
]
